function addFiles(list){window.nativeToolImport(list).then(assets=>{const allowed=toolKindsV15(selectedTool),ok=allowed?assets.filter(a=>allowed.includes(a.kind)):assets,refused=assets.filter(a=>!ok.includes(a));/* 0.15 (Phase 15): one-file tools replace the file instead of listing several */const single=TOOL_ONE_FILE_V15.includes(selectedTool.id);if(single&&ok.length){files=[ok[0]];}else files.push(...ok);renderFiles();if(single&&ok.length>1)notify(selectedTool.name+' works on one file at a time, so '+ok[0].name+' was used.');if(refused.length){const what={video:'videos',image:'images',audio:'audio or video files',pdf:'PDFs'}[allowed.includes('audio')?'audio':allowed[0]];notify((refused.length===1?refused[0].name+' was':refused.length+' files were')+' not added. '+selectedTool.name+' works with '+what+'.');}}).catch(e=>notify(e.message));}function renderFiles(){queueMicrotask(()=>window.nativeToolPreview?.(selectedTool,files));{/* 0.15 (FT-09) */const run=q('[data-action="run-tool"]');if(run){run.disabled=!files.length;run.title=files.length?'':'Add a file first';}}const box=q('#v-filelist');if(!box)return;const first=files[0],start=q('#v-start'),end=q('#v-end');if(first&&start&&end&&end.dataset.asset!==first.id){start.value=0;end.value=Number(first.duration.toFixed(3));start.max=end.max=first.duration;end.dataset.asset=first.id;}box.innerHTML=files.map(fileCardV15).join('');{const drop=q('#v-drop');if(drop){const single=TOOL_ONE_FILE_V15.includes(selectedTool.id);drop.hidden=single&&files.length>0;drop.classList.toggle('compact',files.length>0);const h=drop.querySelector('h3');if(h)h.hidden=files.length>0;const c=drop.querySelector('[data-action="choose-files"]');if(c){c.textContent=files.length?'Add more files':'Choose files';c.classList.toggle('primary',!files.length);}}}fillThumbsV15(box);if(!files.length&&q('#v-result'))q('#v-result').replaceChildren();icons();}
