// 0.15: what is saved for a project: the edit without view settings (tab, track view, selection).
function editorDataV15(){const e=E();return e?.saveData?e.saveData():e?.get();}
// 0.15: edits are saved 400 ms after the last change instead of on every keystroke. flushSaveV15() saves
// at once; the main process calls it before the window closes.
let saveTimerV15=0;
function autosaveSoonV15(){clearTimeout(saveTimerV15);saveTimerV15=setTimeout(()=>{saveTimerV15=0;autosave();},400);}
window.flushSaveV15=()=>{if(saveTimerV15){clearTimeout(saveTimerV15);saveTimerV15=0;autosave();}return true;};
window.addEventListener('pagehide',()=>window.flushSaveV15());
function autosave(){if(restoring)return;let p=s.projects.find(p=>p.id===s.activeProject);const data=editorDataV15();
 /* 0.15 (PR-07): edits made after the last project was deleted get a project of their own instead of being lost */
 if(!p&&data?.clips?.some(c=>c.asset&&c.asset!=='blank')){let n='Untitled video',k=2;while(s.projects.some(x=>x.name===n))n='Untitled video '+(k++);p={id:'p'+Date.now(),name:n,type:'video',when:'Saved locally',snapshot:null};s.projects.unshift(p);s.activeProject=p.id;}
 /* 0.15 (PR-08): only a real change marks a project as edited */
 if(p?.type==='video'){const changed=JSON.stringify(p.snapshot??null)!==JSON.stringify(data??null);p.snapshot=data;if(changed){p.when='Autosaved draft';p.updated=Date.now();}}const savedLabel=q('#ed-save-state');if(savedLabel)savedLabel.textContent='Draft saved locally';persist();}
// 0.15 (PR-02): a failed save is shown in a dialog (once per problem), and a large workspace is mentioned once.
let saveProblemV15='',largeToldV15=false;
function saveOkV15(r){if(saveProblemV15){saveProblemV15='';notify('Saving works again.');}if(r?.large&&!largeToldV15){largeToldV15=true;notify('Your projects take '+Math.round(r.size/1e6)+' MB. Deleting old projects keeps saving quick.');}}
function saveFailedV15(e){const m=e?.message||String(e);notify('Not saved: '+m);if(m===saveProblemV15)return;saveProblemV15=m;if(/paused/i.test(m))return;modal('Your changes are not being saved','<p>'+esc(m)+'</p><p class="v-muted">Keep Video Visor open. After you fix this, the next change saves everything.</p>'+btn('Show projects','go-projects','primary')+btn('OK','close','quiet'));}
function persist(){if(restoring)return;const app={...s,projects:s.projects.map(p=>p.id===s.activeProject?{...p,snapshot:editorDataV15()}:p),route:s.route==='tool'?'home':s.route};window.openai.setWidgetState({privateContent:{prototypeVersion:3,app,editorState:editorDataV15()}}).then(saveOkV15,saveFailedV15);}
