 if(action==='project-delete-confirm'&&project){const wasActive=s.activeProject===project.id,dropMedia=!!q('#v15-del-media')?.checked,mine=[...(project.snapshot?.assets||[]),...(project.versions||[]).flatMap(v=>v.snapshot?.assets||[])].map(a=>a.id);s.projects=s.projects.filter(p=>p!==project);if(dropMedia&&window.native?.storageClean)setTimeout(()=>native.storageClean(usedAssetsV15(),{media:true,only:mine}).then(r=>r.freed&&notify('Deleted its recordings ('+mbV15(r.freed)+').')).catch(e=>notify(e.message)),50);if(wasActive){const next=s.projects.find(p=>p.type==='video');s.activeProject=next?.id||null;if(next?.snapshot)E().set(next.snapshot);else E().reset?.();}closeModal();persist();projects();icons();notify('Project deleted.');}
